//! Compatibility tests against the fixture generated by the Go implementation.

use std::net::IpAddr;

use pm_geoip::{
    as_org_unknown, get_country_info, primitive_network_proximity, Coordinates, CountryInfo,
    Location, Region,
};
use serde::Deserialize;
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/m0/geoip.json");
    let text = std::fs::read_to_string(path).unwrap();
    serde_json::from_str(&text).unwrap()
}

#[test]
fn countries_match_go() {
    let fixture = fixture();
    let countries = fixture["countries"].as_object().unwrap();
    assert!(countries.len() > 200);
    assert_eq!(pm_geoip::countries().len(), countries.len());

    for (code, expected) in countries {
        let expected: CountryInfo = serde_json::from_value(expected.clone()).unwrap();
        let got = get_country_info(code);
        assert_eq!(got, expected, "{code}");
        assert_eq!(got.code, *code);
    }

    // Sampled values from the Go runtime.
    let germany = get_country_info("DE");
    assert_eq!(germany.name, "Germany");
    assert_eq!(germany.center.latitude, 51.0);
    assert_eq!(germany.center.longitude, 10.0);
    assert_eq!(germany.continent.region, "EU-W");
    assert_eq!(germany.continent.name, "Europe");
}

#[test]
fn regions_match_go() {
    let fixture = fixture();
    let regions = fixture["regions"].as_object().unwrap();
    assert_eq!(pm_geoip::regions().len(), regions.len());

    for (id, expected) in regions {
        let expected: Region = serde_json::from_value(expected.clone()).unwrap();
        let got = pm_geoip::regions().get(id).expect("region").clone();
        assert_eq!(got, expected, "{id}");
    }
}

#[derive(Debug, Deserialize)]
struct ProxSpec {
    country: String,
    latitude: f64,
    longitude: f64,
    accuracy: u16,
    asn: u32,
    as_org: String,
    is_anycast: bool,
    is_satellite: bool,
    is_anonymous: bool,
}

impl ProxSpec {
    fn location(&self) -> Location {
        Location {
            country: get_country_info(&self.country),
            coordinates: Coordinates {
                accuracy_radius: self.accuracy,
                latitude: self.latitude,
                longitude: self.longitude,
            },
            asn: self.asn,
            as_org: self.as_org.clone(),
            is_anycast: self.is_anycast,
            is_satellite_provider: self.is_satellite,
            is_anonymous_proxy: self.is_anonymous,
        }
    }
}

#[test]
fn network_proximity_matches_go() {
    let fixture = fixture();
    let cases = fixture["proximity"].as_array().unwrap();
    assert!(!cases.is_empty());

    for case in cases {
        let name = case["name"].as_str().unwrap();
        let from: ProxSpec = serde_json::from_value(case["from"].clone()).unwrap();
        let to: ProxSpec = serde_json::from_value(case["to"].clone()).unwrap();
        let expected = f32::from_bits(case["proximity_bits"].as_u64().unwrap() as u32);

        let got = from.location().estimate_network_proximity(&to.location());
        assert_eq!(got, expected, "{name}");
    }
}

#[test]
fn primitive_proximity_matches_go() {
    let fixture = fixture();
    for case in fixture["primitive_proximity"].as_array().unwrap() {
        let from: IpAddr = case["from"].as_str().unwrap().parse().unwrap();
        let to: IpAddr = case["to"].as_str().unwrap().parse().unwrap();
        let version = case["version"].as_u64().unwrap() as u8;
        let expected = case["expected"].as_i64().unwrap() as i32;
        assert_eq!(
            primitive_network_proximity(from, to, version),
            expected,
            "{} -> {} (v{version})",
            case["from"],
            case["to"]
        );
    }
}

#[test]
fn as_org_unknown_matches_go() {
    let fixture = fixture();
    for case in fixture["as_org_unknown"].as_array().unwrap() {
        let value = case["value"].as_str().unwrap();
        assert_eq!(
            as_org_unknown(value),
            case["expected"].as_bool().unwrap(),
            "{value:?}"
        );
    }
}

#[test]
fn regional_neighbors_follow_the_table() {
    // DE (EU-W) lists EU-S as a neighbor, where ES is located; JP is in AS-E.
    let germany = Location {
        country: get_country_info("DE"),
        ..Location::default()
    };
    let spain = Location {
        country: get_country_info("ES"),
        ..Location::default()
    };
    let japan = Location {
        country: get_country_info("JP"),
        ..Location::default()
    };

    assert!(germany.is_regional_neighbor(&spain));
    assert!(!germany.is_regional_neighbor(&japan));
    // The table lists neighbors symmetrically.
    assert!(spain.is_regional_neighbor(&germany));
    assert!(!Location::default().is_regional_neighbor(&germany));
}
